        opspagev.hideField("supplierBankTap");//银行信息子表格
        opspagev.hideField("descriptionTap");//权限分类
        opspagev.hideField("scoreTable");//合作评分
        opspagev.hideField("OUTap");//财务OU
        opspagev.hideField("supplierBlacklist");//黑名单操作记录表
        opspagev.hideField("companyPhone");//公司电话
        opspagev.hideField("abroadCertificatesCode");//证书号码
        opspagev.hideField("industry");//所属行业
        //opspagev.hideField("organizationType");//机构类型
        opspagev.hideField("businessScope");//经营范围
        opspagev.hideField("businessAdvantage");//经营优势及业务优势
        opspagev.hideField("approvalProgressTitle");//当前审批进度
        opspagev.hideField("approvalTypeName");//审批类型
        opspagev.hideField("approvalNo");//审批单号
        opspagev.hideField("approvalProgress");//审批进度
        opspagev.hideField("approvalHistoryTitle");//审批历史title
        opspagev.hideField("approvalHistory");//审批历史
        if (fieldValue == "1") {
            if (opspagev.formData.supplierType == "1") {
                opspagev.showField("licenseType");//证件类型
                opspagev.showField("licenseCode");//证件号码
                opspagev.showField("name");//姓名
                opspagev.showField("gender");//性别
            } else if (opspagev.formData.supplierType == "0") {
                opspagev.showField("supplierTypeInfo");//供应商类型
                opspagev.showField("supplierNameInfo");//供应商名称
                opspagev.showField("unifiedSocialCertificateCode");//社会统一信用代码
                opspagev.showField("legal");//法人代表
                opspagev.showField("establishDate");//成立日期
                if(opspagev.formData.certificatesEndTime=="2099-12-31"){
                    opspagev.showField("certificatesEndTimeStr");//证件有效期至
                }else{
                    opspagev.showField("certificatesEndTime");//证件有效期至
                }
                //opspagev.showField("companyType");//企业类别
                opspagev.showField("currency");//注册币种
                opspagev.showField("address");//注册地址
