                //opspagev.showField("listFlag");//是否上市公司
                //opspagev.showField("branchFlag");//是否分支机构
                opspagev.showField("companyNature");//企业性质
                opspagev.showField("capital");//capital
                opspagev.showField("industry");//所属行业
                //opspagev.showField("organizationType");//机构类型
                opspagev.showField("businessScope");//经营范围
                opspagev.showField("businessAdvantage");//经营优势及业务优势
            } else if (opspagev.formData.supplierType == "2") {
                opspagev.showField("supplierTypeInfo");//供应商类型
                opspagev.showField("supplierNameInfo");//供应商名称
                opspagev.showField("address");//注册地址
            } else if (opspagev.formData.supplierType == "3") {
                opspagev.showField("supplierTypeInfo");//供应商类型
                opspagev.showField("supplierNameInfo");//供应商名称
                opspagev.showField("abroadCertificatesCode");//证书号码
                opspagev.showField("establishDate");//成立日期
                if(opspagev.formData.certificatesEndTime=="2099-12-31"){
                    opspagev.showField("certificatesEndTimeStr");//证件有效期至
                }else{
                    opspagev.showField("certificatesEndTime");//证件有效期至
                }
                opspagev.showField("legal");//法人代表
                opspagev.showField("capital");//注册资金
                opspagev.showField("currency");//注册币种
                opspagev.showField("address");//注册地址
                opspagev.showField("companyPhone");//公司电话
            }


        } else if (fieldValue == "2") {
            var result = OPSExecInterface(ipPort + "/supplier/supplierContact", { "supplierId": supplierId }, "GET");
            if (result.Message == "供应商名称已存在！") { }
            console.log("联系人查询" + result)
            if (result.Content != null & result.Content != "") {
                var data = JSON.parse(result.Content)
                opspagev.formData.supplierContact = [];
                for (var i = 0; i < data.length; i++) {
                    var name = data[i].name;
                    var gender = data[i].gender + "";
                    var telephone = data[i].telephone;
                    var email = data[i].email;
                    var department = data[i].department;
                    var duties = data[i].duties;
                    var remark = data[i].remark;
                    opspagev.formData.supplierContact.push({ "name": name, "gender": gender, "telephone": telephone, "email": email, "department": department, "duties": duties, "remark": remark })
                }

            }
            if(opspagev.formData.invitationAction == "0"){
                opspagev.setSubTableColumnVisible("supplierContact", "telephone", false)
            }else if(opspagev.formData.invitationAction == "1"){
                opspagev.setSubTableColumnVisible("supplierContact", "telephone", true)
            }
            opspagev.showField("supplierContact");


        } else if (fieldValue == "3") {

            var result = OPSExecInterface(ipPort + "/supplier/supplierBank", { "supplierId": supplierId }, "GET");
            console.log("银行信息查询：" + result)
            if (result.Content != null & result.Content != "") {
                var data = JSON.parse(result.Content)
                opspagev.formData.supplierBankTap = []
                for (var i = 0; i < data.length; i++) {
                    var accountType = data[i].accountType + "";
                    var bank = data[i].bank;
                    var branchBank = data[i].branchBank;
                    var accountName = data[i].accountName;
                    var province = data[i].province;
                    var city = data[i].city;
                    var accountNumber = data[i].accountNumber;
                    var remark = data[i].remark;
                    var country = data[i].country;
                    var currency = data[i].currencyCode + "";
                    opspagev.formData.supplierBankTap.push({ "accountType": accountType, "accountNumber": accountNumber, "bank": bank, "branchBank": branchBank, "accountName": accountName, "province": province, "city": city, "remark": remark, "country": country, "currency": currency })
                }

            }

            if (opspagev.formData.supplierType != "0") {
                opspagev.setSubTableColumnVisible("supplierBankTap", "accountType", false)
            }

            opspagev.showField("supplierBankTap");
        } else if (fieldValue == "4") {
            var result = OPSExecInterface(ipPort + "/supplier/supplierBusiness", { "supplierId": supplierId }, "GET");
            console.log("所属业务接口查询：" + result)
            if (result.Content != null & result.Content != "") {
                var data = JSON.parse(result.Content);
                opspagev.formData.descriptionTap = []
                for (var i = 0; i < data.length; i++) {
                    opspagev.formData.descriptionTap.push({ "ownedBusiness": data[i].ownedBusiness + "", "businessCategory": data[i].businessCategory + "", "remark": data[i].remark })
                }


            }
            opspagev.showField("descriptionTap");
        } else if (fieldValue == "5") {
            var result = OPSExecInterface(ipPort + "/supplier/supplierFinanceOU", { "supplierId": supplierId }, "GET");
            console.log("ou查询" + result)
            if (result.Content != null & result.Content != "") {
                var data = JSON.parse(result.Content)

                opspagev.formData.OUTap = [];
                for (var i = 0; i < data.length; i++) {
                    var orgName = data[i].orgName;//业务实体名称
                    var liaConcatenatedSegments = data[i].liaConcatenatedSegments;//负债
                    var prepayConcatenatedSegments = data[i].prepayConcatenatedSegments;//预付款
                    var addressOU = data[i].addressOu
                    opspagev.formData.OUTap.push({ "orgName": orgName, "liaConcatenatedSegments": liaConcatenatedSegments, "prepayConcatenatedSegments": prepayConcatenatedSegments,"addressOU":addressOU });
                }
            }
            opspagev.showField("OUTap");

        } else if (fieldValue == "6") {
            var result = OPSExecInterface(ipPort + "/supplier/supplierBlacklist", { "supplierId": supplierId }, "GET");
            console.log("黑名单查询" + result)
            if (result.Content != null & result.Content != "") {
                var data = JSON.parse(result.Content)
                opspagev.formData.supplierBlacklist = []
                for (var i = 0; i < data.length; i++) {
                    var createUser = data[i].createUser;//拉黑操作人
                    var status = data[i].status + "";//状态
                    var updateTime = data[i].updateTime;//移除时间
                    var createTime = data[i].createTime;//拉黑时间
                    var applyReason = data[i].applyReason;//拉黑原因
                    var updateUser = data[i].updateUser;//移除操作人
                    var removeReason = data[i].removeReason;//移除原因
                    if (updateTime <= createTime) {
                        updateTime = "";
                        updateUser = "";
                    }
                    opspagev.formData.supplierBlacklist.push({ "createUser": createUser, "status": status, "updateTime": updateTime, "createTime": createTime, "applyReason": applyReason, "updateUser": updateUser, "removeReason": removeReason });
                }
            }
            opspagev.showField("supplierBlacklist");

        }else if (fieldValue == "7") {
            opspagev.showField("approvalProgressTitle");//当前审批进度
            opspagev.showField("approvalTypeName");//审批类型
            opspagev.showField("approvalNo");//审批单号
            opspagev.showField("approvalProgress");//审批进度
            opspagev.showField("approvalHistoryTitle");//审批历史title
            opspagev.showField("approvalHistory");//审批历史
        }else if (fieldValue == "8") {
            opspagev.showField("scoreTable");//合作评分
        }

    }


    try{
        opspagev.refreshCustomSearchList("scoreTable");
    }catch(e){

    }
}


