        opspagev.showField("supplierTypeInfo");//供应商类型
        opspagev.showField("supplierNameInfo");//供应商名称
        opspagev.showField("abroadCertificatesCode");//证书号码
        opspagev.showField("establishDate");//成立日期
        if(opspagev.formData.certificatesEndTime=="2099-12-31"){
            opspagev.showField("certificatesEndTimeStr");//证件有效期至
        }else{
            opspagev.showField("certificatesEndTime");//证件有效期至
        }
        opspagev.showField("legal");//法人代表
        opspagev.showField("capital");//注册资金
        opspagev.showField("currency");//注册币种
        opspagev.showField("address");//注册地址
        opspagev.showField("companyPhone");//公司电话
    }

    var supplierCode = opspagev.formData.supplierCode;
    var resultProgress = OPSExecInterface("{approval-test}/approval/approvalProgress", { "supplierCode": supplierCode }, "GET");
    var dataProgress = JSON.parse(resultProgress.Content)
    console.log("dataProgress : "+ JSON.stringify(dataProgress))
    if(dataProgress[0] != null && dataProgress[0] != ''){
        opspagev.formData.approvalNo =dataProgress[0].approvalNo ;

        opspagev.formData.approvalTypeName = dataProgress[0].approvalTypeName;
        var wflProcessFlowLogDtoList = dataProgress[0].wflProcessFlowLogDtoList;
        if(wflProcessFlowLogDtoList != null && wflProcessFlowLogDtoList !=''){
            for (var i = 0; i < wflProcessFlowLogDtoList.length; i++) {
                opspagev.formData.approvalProgress.push({
                    "approveUser":wflProcessFlowLogDtoList[i].approveUser,
                    "approveAgentOrg":wflProcessFlowLogDtoList[i].approveAgentOrg ,
                    "nodeName":wflProcessFlowLogDtoList[i].nodeName ,
                    "approveTime":wflProcessFlowLogDtoList[i].approveTime ,

                    "approveIdea":wflProcessFlowLogDtoList[i].approveIdea,
                    "ApproveTypeCode":wflProcessFlowLogDtoList[i].approveTypeCode

                })

            }
        }
    }
    var resultHistory = OPSExecInterface("{approval-test}/approval/approvalHistory", { "supplierCode": supplierCode }, "GET");
    var dataHistory = JSON.parse(resultHistory.Content)
    if(dataHistory.length >0){
        for (var i = 0; i < dataHistory.length; i++) {
            opspagev.formData.approvalHistory.push({
                "approvalNo":dataHistory[i].approvalNo ,
                "approvalTypeName":dataHistory[i].approvalTypeName ,
                "approvalStatusName":dataHistory[i].statusName ,
                "startTime":dataHistory[i].startTime ,
                "promoter":dataHistory[i].promoter
            })

        }
    }

    var butType = opspagev.formData.buttonType;
    if(butType!=null && butType!='' && butType=="1"){
        opspagev.formData.taps="8"
    }
}

